//   - UPDATE (non-empty oldRef): UPDATE ... WHERE current_ref = oldRef RETURNING
//     version. A moved or absent head matches no row (pgx.ErrNoRows) →
//     ErrFactRefConflict.
//
// Either way the swap is atomic: Postgres row-locks the (repo_key, branch) key for
// the statement, so two concurrent Advances against the same head serialize and
// exactly one wins — the loser sees the other's committed value and its WHERE
// clause matches nothing.
func (s *PgFactRefIndex) Advance(ctx context.Context, repoKey, branch, oldRef, newRef string) (int64, error) {
	if err := ctx.Err(); err != nil {
		return 0, err
	}
	if repoKey == "" || branch == "" {
		return 0, errors.New("brainbuild: empty repoKey/branch in Advance")
	}
	if newRef == "" {
		return 0, errors.New("brainbuild: empty newRef in Advance (a head always points at content)")
	}

	// CREATE (empty oldRef): no superseded coordinate to shred; a single statement.
	if oldRef == "" {
		var next int64
		err := s.pool.QueryRow(ctx, `
			INSERT INTO brain_fact_refs (repo_key, branch, current_ref, version)
			VALUES ($1, $2, $3, 1)
			ON CONFLICT (repo_key, branch) DO NOTHING
			RETURNING version`,
			repoKey, branch, newRef).Scan(&next)
		if errors.Is(err, pgx.ErrNoRows) {
			return 0, ErrFactRefConflict
		}
		if err != nil {
			return 0, fmt.Errorf("brainbuild: advance fact-set head %s/%s: %w", repoKey, branch, err)
		}
		return next, nil
	}

	// UPDATE + CRYPTO-SHRED the superseded coordinate, atomically in one tx: the CAS
	// moves this branch off oldRef, then — IFF no branch (in this repo) still references
	// oldRef — the old fact-set's DEK is dropped, rendering its plaintext unrecoverable
	// at rest (the crypto-shred guarantee for facts). The NOT EXISTS runs AFTER the CAS
	// in the SAME tx, so a sibling branch still on oldRef keeps the DEK live; only a
	// genuinely orphaned coordinate is shredded. brain_deks grants repo_rw DELETE (044).
	tx, err := s.pool.Begin(ctx)
	if err != nil {
		return 0, fmt.Errorf("brainbuild: advance begin %s/%s: %w", repoKey, branch, err)
	}
	defer tx.Rollback(ctx) //nolint:errcheck // no-op after a successful Commit

	var next int64
	err = tx.QueryRow(ctx, `
		UPDATE brain_fact_refs
		SET current_ref = $3, version = version + 1, updated_at = now()
		WHERE repo_key = $1 AND branch = $2 AND current_ref = $4
		RETURNING version`,
		repoKey, branch, newRef, oldRef).Scan(&next)
	if errors.Is(err, pgx.ErrNoRows) {
		return 0, ErrFactRefConflict
	}
	if err != nil {
		return 0, fmt.Errorf("brainbuild: advance fact-set head %s/%s: %w", repoKey, branch, err)
	}

	if _, err := tx.Exec(ctx, `
		DELETE FROM brain_deks
		WHERE repo_key = $1 AND kind = $2 AND ref = $3
		  AND NOT EXISTS (
		    SELECT 1 FROM brain_fact_refs WHERE repo_key = $1 AND current_ref = $3
		  )
		  AND NOT EXISTS (
		    SELECT 1 FROM brain_fact_proposals
		    WHERE repo_key = $1 AND content_ref = $3 AND status = '`+ProposalStatusOpen+`'
		  )`,
		repoKey, brainstore.KindFacts, oldRef); err != nil {
		return 0, fmt.Errorf("brainbuild: shred superseded fact-set DEK %s/%s@%s: %w", repoKey, branch, oldRef, err)
	}

	if err := tx.Commit(ctx); err != nil {
		return 0, fmt.Errorf("brainbuild: advance commit %s/%s: %w", repoKey, branch, err)
	}
	return next, nil
}

