package httpapi

import (
	"context"
	"encoding/json"
	"net/http"
	"testing"

	"github.com/danielgtaylor/huma/v2"

	"github.com/entirehq/entire-api/internal/brainbuild"
	"github.com/entirehq/entire-api/internal/brainstore"
	"github.com/entirehq/entire-api/internal/snapshotcrypt/snapshotcrypttest"
)

// newProposalsTest wires Mem-backed fact-set AND proposal-set heads behind
// RepoActivityDeps. They share the encrypting store (as production does) but hold
// SEPARATE ref indexes, which is the point: the two heads must move independently.
func newProposalsTest() *RepoActivityDeps {
	inner := brainstore.NewMemStore()
	enc := brainstore.NewEncryptingStore(inner, snapshotcrypttest.NewCipher(), brainstore.NewMemDEKStore())
	resolver := fakeSlugResolver{slug: factsSlug}
	facts := brainbuild.NewFactSetStore(enc, brainbuild.NewMemFactRefIndex(), resolver)
	proposals := brainbuild.NewProposalSetStore(enc, brainbuild.NewMemFactRefIndex(), resolver)
	return &RepoActivityDeps{Facts: facts, Proposals: proposals}
}

// proposalEntry builds one set entry with the client's shape: a derived id plus an
// opaque proposal body the server never interprets.
func proposalEntry(t *testing.T, id, action, candidate, target string) brainProposal {
	t.Helper()
	body, err := json.Marshal(map[string]any{
		"action":       action,
		"candidate_id": candidate,
		"target_id":    target,
		"branch":       factsBranch,
		"proposed_by":  "member-A",
	})
	if err != nil {
		t.Fatal(err)
	}
	return brainProposal{ID: id, Proposal: body}
}

func publishInput(branch, oldRef string, set []brainProposal) *BrainProposalsPublishInput {
	in := &BrainProposalsPublishInput{RepoID: factsRepoID}
	in.Body.Branch = branch
	in.Body.OldRef = oldRef
	in.Body.Proposals = set
	return in
}

func resolveInput(branch, id, decision, factsOldRef string, data []byte, setOldRef string, remaining []brainProposal) *BrainProposalResolveInput {
	in := &BrainProposalResolveInput{RepoID: factsRepoID, ProposalID: id}
	in.Body.Branch = branch
	in.Body.Decision = decision
	in.Body.FactsOldRef = factsOldRef
	in.Body.Data = data
	in.Body.ProposalsOldRef = setOldRef
	in.Body.Proposals = remaining
	return in
}

func statusOf(t *testing.T, err error) int {
	t.Helper()
	var se huma.StatusError
	if !asStatusError(err, &se) {
		t.Fatalf("expected a huma.StatusError, got %v", err)
	}
	return se.GetStatus()
}

func asStatusError(err error, out *huma.StatusError) bool {
	se, ok := err.(huma.StatusError)
	if ok {
		*out = se
	}
	return ok
}

// TestProposalsPublishThenList: an empty branch lists found=false with an empty set;
// after a publish the set round-trips through the CAS'd blob unchanged, including the
// opaque proposal body.
func TestProposalsPublishThenList(t *testing.T) {
	deps := newProposalsTest()
	ctx := context.Background()

	empty, err := listBrainProposals(ctx, deps, &BrainProposalsListInput{RepoID: factsRepoID, Branch: factsBranch})
	if err != nil {
		t.Fatalf("list empty: %v", err)
	}
	if empty.Body.Found {
		t.Fatal("a branch with no set must read found=false")
	}
	if empty.Body.Proposals == nil || len(empty.Body.Proposals) != 0 {
		t.Fatalf("empty set must be an empty array, not null: %+v", empty.Body.Proposals)
	}

	set := []brainProposal{proposalEntry(t, "prop-aaaa", "supersede", "fact:a", "fact:b")}
	pub, err := publishBrainProposals(ctx, deps, publishInput(factsBranch, "", set))
	if err != nil {
		t.Fatalf("publish: %v", err)
	}
	if !pub.Body.Changed || pub.Body.Ref == "" {
		t.Fatalf("publish should have created a head: %+v", pub.Body)
	}

	got, err := listBrainProposals(ctx, deps, &BrainProposalsListInput{RepoID: factsRepoID, Branch: factsBranch})
	if err != nil {
		t.Fatalf("list: %v", err)
	}
	if !got.Body.Found || len(got.Body.Proposals) != 1 {
		t.Fatalf("published set did not round-trip: %+v", got.Body)
	}
	if got.Body.Proposals[0].ID != "prop-aaaa" {
		t.Fatalf("client-derived id was not preserved: %q", got.Body.Proposals[0].ID)
	}
	// The server must not reinterpret the proposal body.
	var decoded map[string]any
	if err := json.Unmarshal(got.Body.Proposals[0].Proposal, &decoded); err != nil {
		t.Fatalf("proposal body is not intact JSON: %v", err)
	}
	if decoded["candidate_id"] != "fact:a" || decoded["proposed_by"] != "member-A" {
		t.Fatalf("proposal body was altered: %+v", decoded)
	}
}

// TestProposalsPublishStaleOldRefConflicts: a publish from a ref another member has
// already moved past must lose the CAS with 412, never clobber.
func TestProposalsPublishStaleOldRefConflicts(t *testing.T) {
	deps := newProposalsTest()
	ctx := context.Background()

	first, err := publishBrainProposals(ctx, deps, publishInput(factsBranch, "",
		[]brainProposal{proposalEntry(t, "prop-aaaa", "supersede", "fact:a", "fact:b")}))
	if err != nil {
		t.Fatalf("first publish: %v", err)
	}
	if _, err := publishBrainProposals(ctx, deps, publishInput(factsBranch, first.Body.Ref,
		[]brainProposal{proposalEntry(t, "prop-bbbb", "merge", "fact:c", "fact:d")})); err != nil {
		t.Fatalf("second publish: %v", err)
	}
	// Third publish still quotes the FIRST ref: stale.
	_, err = publishBrainProposals(ctx, deps, publishInput(factsBranch, first.Body.Ref,
		[]brainProposal{proposalEntry(t, "prop-cccc", "merge", "fact:e", "fact:f")}))
	if err == nil {
		t.Fatal("a stale oldRef must not win the CAS")
	}
	if got := statusOf(t, err); got != http.StatusPreconditionFailed {
		t.Fatalf("stale publish status = %d, want 412", got)
	}
}

// TestProposalResolveAdvancesBothHeads is the settlement path: the runner sends the
// resolved fact set and the remaining proposals, each under the ref it read, and both
// heads move together.
func TestProposalResolveAdvancesBothHeads(t *testing.T) {
	deps := newProposalsTest()
	ctx := context.Background()

	// A fact head to settle against.
	factsAdv, err := advanceBrainFacts(ctx, deps, advanceInput(factsBranch, "", []byte(`{"id":"fact:a"}`)))
	if err != nil {
		t.Fatalf("seed facts: %v", err)
	}
	set := []brainProposal{
		proposalEntry(t, "prop-aaaa", "supersede", "fact:a", "fact:b"),
		proposalEntry(t, "prop-bbbb", "merge", "fact:c", "fact:d"),
	}
	pub, err := publishBrainProposals(ctx, deps, publishInput(factsBranch, "", set))
	if err != nil {
		t.Fatalf("publish: %v", err)
	}

	res, err := resolveBrainProposal(ctx, deps, resolveInput(
		factsBranch, "prop-aaaa", "accept",
		factsAdv.Body.NewRef, []byte(`{"id":"fact:a","resolved":true}`),
		pub.Body.Ref, set[1:],
	))
	if err != nil {
		t.Fatalf("resolve: %v", err)
	}
	if res.Body.FactsRef == factsAdv.Body.NewRef {
		t.Fatal("accept did not advance the fact head")
	}
	if res.Body.ProposalsRef == pub.Body.Ref {
		t.Fatal("resolve did not advance the proposal set")
	}

	after, err := listBrainProposals(ctx, deps, &BrainProposalsListInput{RepoID: factsRepoID, Branch: factsBranch})
	if err != nil {
		t.Fatal(err)
	}
	if len(after.Body.Proposals) != 1 || after.Body.Proposals[0].ID != "prop-bbbb" {
		t.Fatalf("settled entry was not removed from the set: %+v", after.Body.Proposals)
	}
}

// TestProposalResolveFactsUnchangedPrunesWithoutTouchingFacts covers the orphan path:
// a proposal whose facts are gone cannot be accepted, and reject changes no facts, so
// the settlement must move ONLY the proposal set and leave the fact head exactly where
// it was.
func TestProposalResolveFactsUnchangedPrunesWithoutTouchingFacts(t *testing.T) {
	deps := newProposalsTest()
	ctx := context.Background()

	factsAdv, err := advanceBrainFacts(ctx, deps, advanceInput(factsBranch, "", []byte(`{"id":"fact:a"}`)))
	if err != nil {
		t.Fatalf("seed facts: %v", err)
	}
	set := []brainProposal{proposalEntry(t, "prop-orphan", "supersede", "fact:gone", "fact:alsogone")}
	pub, err := publishBrainProposals(ctx, deps, publishInput(factsBranch, "", set))
	if err != nil {
		t.Fatalf("publish: %v", err)
	}

	in := resolveInput(factsBranch, "prop-orphan", "reject", factsAdv.Body.NewRef, nil, pub.Body.Ref, nil)
	in.Body.FactsUnchanged = true
	res, err := resolveBrainProposal(ctx, deps, in)
	if err != nil {
		t.Fatalf("prune: %v", err)
	}
	if res.Body.FactsRef != factsAdv.Body.NewRef {
		t.Fatalf("prune moved the fact head: %q -> %q", factsAdv.Body.NewRef, res.Body.FactsRef)
	}

	cur, err := currentBrainFacts(ctx, deps, currentInput(factsBranch))
	if err != nil {
		t.Fatal(err)
	}
	if cur.Body.Ref != factsAdv.Body.NewRef {
		t.Fatalf("fact head changed behind a facts-unchanged prune: %q", cur.Body.Ref)
	}
	after, err := listBrainProposals(ctx, deps, &BrainProposalsListInput{RepoID: factsRepoID, Branch: factsBranch})
	if err != nil {
		t.Fatal(err)
	}
	if len(after.Body.Proposals) != 0 {
		t.Fatalf("orphan was not pruned: %+v", after.Body.Proposals)
	}
}

// TestProposalResolveRejectsFactsUnchangedOnAccept guards the boundary: skipping the
// fact write on an accept would retire the proposal while dropping its merge result.
func TestProposalResolveRejectsFactsUnchangedOnAccept(t *testing.T) {
	deps := newProposalsTest()
	in := resolveInput(factsBranch, "prop-aaaa", "accept", "", nil, "", nil)
	in.Body.FactsUnchanged = true
	_, err := resolveBrainProposal(context.Background(), deps, in)
	if err == nil {
		t.Fatal("factsUnchanged with accept must be refused")
	}
	if got := statusOf(t, err); got != http.StatusBadRequest {
		t.Fatalf("status = %d, want 400", got)
	}
}

// TestProposalResolveStaleSetRefConflicts: losing the proposal-set CAS is a 412 so
// the runner re-reads and re-resolves rather than clobbering a concurrent settlement.
func TestProposalResolveStaleSetRefConflicts(t *testing.T) {
	deps := newProposalsTest()
	ctx := context.Background()

	factsAdv, err := advanceBrainFacts(ctx, deps, advanceInput(factsBranch, "", []byte(`{"id":"fact:a"}`)))
	if err != nil {
		t.Fatal(err)
	}
	set := []brainProposal{proposalEntry(t, "prop-aaaa", "supersede", "fact:a", "fact:b")}
	pub, err := publishBrainProposals(ctx, deps, publishInput(factsBranch, "", set))
	if err != nil {
		t.Fatal(err)
	}
	// Someone else moves the set first.
	if _, err := publishBrainProposals(ctx, deps, publishInput(factsBranch, pub.Body.Ref,
		[]brainProposal{proposalEntry(t, "prop-zzzz", "merge", "fact:y", "fact:z")})); err != nil {
		t.Fatal(err)
	}
	_, err = resolveBrainProposal(ctx, deps, resolveInput(
		factsBranch, "prop-aaaa", "accept",
		factsAdv.Body.NewRef, []byte(`{"id":"fact:a","resolved":true}`),
		pub.Body.Ref, nil, // stale set ref
	))
	if err == nil {
		t.Fatal("a stale proposalsOldRef must not win")
	}
	if got := statusOf(t, err); got != http.StatusPreconditionFailed {
		t.Fatalf("status = %d, want 412", got)
	}
}

// TestProposalsNilStoreUnavailable: an unconfigured queue fails closed with 503 on
// every endpoint rather than pretending the set is empty.
func TestProposalsNilStoreUnavailable(t *testing.T) {
	deps := &RepoActivityDeps{} // Proposals nil
	ctx := context.Background()
	if _, err := listBrainProposals(ctx, deps, &BrainProposalsListInput{RepoID: factsRepoID, Branch: factsBranch}); err == nil {
		t.Fatal("list with no store must fail")
	} else if got := statusOf(t, err); got != http.StatusServiceUnavailable {
		t.Fatalf("list status = %d, want 503", got)
	}
	if _, err := publishBrainProposals(ctx, deps, publishInput(factsBranch, "", nil)); err == nil {
		t.Fatal("publish with no store must fail")
	} else if got := statusOf(t, err); got != http.StatusServiceUnavailable {
		t.Fatalf("publish status = %d, want 503", got)
	}
}

// TestProposalGetReportsAbsentAsFound false, not 404: "settled by someone else" is a
// normal answer a reconciling client must be able to tell from a failed request.
func TestProposalGetReportsAbsentAsFound(t *testing.T) {
	deps := newProposalsTest()
	ctx := context.Background()
	set := []brainProposal{proposalEntry(t, "prop-aaaa", "supersede", "fact:a", "fact:b")}
	if _, err := publishBrainProposals(ctx, deps, publishInput(factsBranch, "", set)); err != nil {
		t.Fatal(err)
	}
	got, err := getBrainProposal(ctx, deps, &BrainProposalGetInput{RepoID: factsRepoID, ProposalID: "prop-missing", Branch: factsBranch})
	if err != nil {
		t.Fatalf("absent proposal must not be an error: %v", err)
	}
	if got.Body.Found || got.Body.Proposal != nil {
		t.Fatalf("absent proposal reported as found: %+v", got.Body)
	}
	present, err := getBrainProposal(ctx, deps, &BrainProposalGetInput{RepoID: factsRepoID, ProposalID: "prop-aaaa", Branch: factsBranch})
	if err != nil {
		t.Fatal(err)
	}
	if !present.Body.Found || present.Body.Proposal == nil {
		t.Fatalf("present proposal not returned: %+v", present.Body)
	}
}

