// TestProposalWireContractMatchesBrainClient pins the cross-repo contract. The literals
// below are the exact JSON entire-brain's internal/factsync HTTP client emits and
// expects (see its httpproposals.go header comment); this test decodes those bytes into
// the server's input types and encodes the server's outputs back.
//
// It exists because the two halves live in different repos and cannot import each
// other, so nothing else makes a rename or a retyped field fail a build. Both sides
// previously drifted into three incompatibilities at once — different paths, a
// different settle verb, and different proposal-id derivations — with every unit test
// on both sides passing.
func TestProposalWireContractMatchesBrainClient(t *testing.T) {
	t.Run("publish request", func(t *testing.T) {
		// factsync.publishProposalsBody
		raw := []byte(`{"branch":"main","oldRef":"proposals-abc","proposals":[{"id":"prop-1234","proposal":{"action":"supersede","candidate_id":"fact:a","target_id":"fact:b","branch":"main","proposed_by":"member-A"}}]}`)
		var in BrainProposalsPublishInput
		if err := json.Unmarshal(raw, &in.Body); err != nil {
			t.Fatalf("server cannot decode the client's publish body: %v", err)
		}
		if in.Body.Branch != "main" || in.Body.OldRef != "proposals-abc" {
			t.Fatalf("publish fields lost: %+v", in.Body)
		}
		if len(in.Body.Proposals) != 1 || in.Body.Proposals[0].ID != "prop-1234" {
			t.Fatalf("client-derived id lost: %+v", in.Body.Proposals)
		}
	})

	t.Run("resolve request", func(t *testing.T) {
		// factsync.resolveRequestBody — data is base64 because encoding/json renders []byte so.
		raw := []byte(`{"branch":"main","decision":"accept","factsOldRef":"facts-old","data":"eyJpZCI6ImZhY3Q6YSJ9","factsUnchanged":false,"proposalsOldRef":"proposals-old","proposals":[]}`)
		var in BrainProposalResolveInput
		if err := json.Unmarshal(raw, &in.Body); err != nil {
			t.Fatalf("server cannot decode the client's resolve body: %v", err)
		}
		if in.Body.Decision != "accept" || in.Body.FactsOldRef != "facts-old" || in.Body.ProposalsOldRef != "proposals-old" {
			t.Fatalf("resolve fields lost: %+v", in.Body)
		}
		if string(in.Body.Data) != `{"id":"fact:a"}` {
			t.Fatalf("base64 data did not decode to the resolved fact set: %q", in.Body.Data)
		}
		if in.Body.Proposals == nil {
			t.Fatal("an explicit empty proposals array must decode as empty, not nil: it CLEARS the set")
		}
	})

	t.Run("resolve request with factsUnchanged", func(t *testing.T) {
		raw := []byte(`{"branch":"main","decision":"reject","factsOldRef":"facts-old","data":null,"factsUnchanged":true,"proposalsOldRef":"proposals-old","proposals":[]}`)
		var in BrainProposalResolveInput
		if err := json.Unmarshal(raw, &in.Body); err != nil {
			t.Fatalf("server cannot decode the orphan-prune body: %v", err)
		}
		if !in.Body.FactsUnchanged || in.Body.Decision != "reject" {
			t.Fatalf("prune signal lost: %+v", in.Body)
		}
	})

	t.Run("list response", func(t *testing.T) {
		// factsync.wireProposalSet reads found/ref/version/proposals.
		out := &BrainProposalsListOutput{}
		out.Body.Found = true
		out.Body.Ref = "proposals-abc"
		out.Body.Version = 3
		out.Body.Proposals = []brainProposal{{ID: "prop-1234", Proposal: json.RawMessage(`{"action":"merge"}`)}}
		encoded, err := json.Marshal(out.Body)
		if err != nil {
			t.Fatal(err)
		}
		var client struct {
			Found     bool   `json:"found"`
			Ref       string `json:"ref"`
			Version   int64  `json:"version"`
			Proposals []struct {
				ID       string          `json:"id"`
				Proposal json.RawMessage `json:"proposal"`
			} `json:"proposals"`
		}
		if err := json.Unmarshal(encoded, &client); err != nil {
			t.Fatalf("client cannot decode the server's list response: %v", err)
		}
		if !client.Found || client.Ref != "proposals-abc" || client.Version != 3 {
			t.Fatalf("list envelope fields lost: %s", encoded)
		}
		if len(client.Proposals) != 1 || client.Proposals[0].ID != "prop-1234" {
			t.Fatalf("proposal entry lost: %s", encoded)
		}
	})

	t.Run("resolve response", func(t *testing.T) {
		out := &BrainProposalResolveOutput{}
		out.Body.FactsRef = "facts-new"
		out.Body.ProposalsRef = "proposals-new"
		out.Body.Changed = true
		encoded, err := json.Marshal(out.Body)
		if err != nil {
			t.Fatal(err)
		}
		var client struct {
			FactsRef     string `json:"factsRef"`
			ProposalsRef string `json:"proposalsRef"`
			Changed      *bool  `json:"changed"`
		}
		if err := json.Unmarshal(encoded, &client); err != nil {
			t.Fatalf("client cannot decode the server's resolve response: %v", err)
		}
		if client.FactsRef != "facts-new" || client.ProposalsRef != "proposals-new" || client.Changed == nil || !*client.Changed {
			t.Fatalf("resolve response fields lost: %s", encoded)
		}
	})
}
